function gxEditor(row,q){Object.assign(GP_TYPES,GX_TYPES);gpEditorRow(row,q);row.querySelector('h4').textContent=GX_TYPES[q.geo.kind.slice(3)];row.querySelector('.gp-wide').textContent='Grid cell IDs run 0–5 across the top row through 24–29 at the bottom. Sculpting uses 24 cells in four strips. Save checks the field values; play-test your edited model and update its brief before teaching.';const help=row.querySelector('.gp-editor-help');help.textContent='This is a Geography adventure, with no answer choices. Edit the mission evidence and expand the settings to change the model, map, route or creation brief. Review the instructions when changing its data.';}
document.addEventListener('DOMContentLoaded',()=>{const previous=window.render_game_to_text;window.render_game_to_text=()=>{const text=JSON.parse(previous());if(game?.session?.geography){text.geographyRelease='adventures-2026-09-13';text.adventures=game.session.lanes.map(l=>({name:l.name,kind:game.items[l.index]?.geo?.kind,phase:l.phase,state:l.gx,task:game.items[l.index]?.geo.task}));text.coordinateSystem='Grid: A–F west to east, rows 1–5 north to south, cell IDs 0–29. Studio drawing coordinates 600×240. No multiple-choice Geography controls.';}return JSON.stringify(text);};});

document.addEventListener('DOMContentLoaded',()=>{const gxPreviousRenderRows=renderRows;renderRows=()=>{gxPreviousRenderRows();const geo=draft?.subject==='geography';document.querySelector('.editor-heading p').textContent=geo?'Adapt the mission evidence, maps and model settings for your lesson.':'Use the prepared questions, or change anything below.';const heading=document.querySelector('#question-count').parentElement;heading.firstChild.textContent=geo?'Missions ':'Questions ';document.querySelector('#paste-toggle').hidden=geo;if(geo)document.querySelector('#paste-panel').hidden=true;document.querySelector('#add-question').textContent=geo?'+ Add creation mission':'+ Add question';};if(draft&&ui.view==='editor')renderRows();});
